import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { trpc } from "@/lib/trpc";
import type { inferRouterOutputs } from "@trpc/server";
import type { AppRouter } from "../../../server/routers";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { confirmAction, promptAction } from "@/lib/confirm";
import { WATTFOX, WATTFOX_TEMPLATE, isTestAddress, isWattfoxTemplate, wattfoxOriginCheck, wattfoxTemplateWithAgreedOrigin } from "../../../shared/wattfox";
import { Eye, EyeOff } from "lucide-react";
import { SAVED_SECRET, isPlainCredential } from "../../../shared/credentials";
import { GLUED_ADDRESS_HINT, hasGluedAddress } from "../../../shared/endpoint-url";
import BuyerFeedback from "@/components/BuyerFeedback";

type Integration = inferRouterOutputs<AppRouter>["leadops"]["getMemberIntegration"];
type Endpoint = Integration["endpoints"][number];
type Rule = Integration["rules"][number];
const field = "h-10 w-full rounded-md border border-white/10 bg-slate-900 px-3 text-sm text-slate-100";
const Toggle = ({ checked, onChange, label, hint }: { checked: boolean; onChange: (value: boolean) => void; label: string; hint?: string }) => <label className="flex items-start gap-3 rounded-lg border border-white/8 bg-white/[.02] p-3 text-sm text-slate-200"><input type="checkbox" className="mt-1" checked={checked} onChange={(event) => onChange(event.target.checked)} /><span><span className="block">{label}</span>{hint && <span className="mt-0.5 block text-xs text-slate-400">{hint}</span>}</span></label>;
const emptyEndpoint = (categoryId: number): Endpoint => ({ id: 0, categoryId, enabled: true, method: "POST", url: "", sourceFilterMode: "alle", sourceSupplierIds: [], fieldFilters: [], headers: [], authEnabled: false, auth: null, bodyTemplate: "", omitAutoFields: false, rotate: false, valueMappings: [], sentCount: 0, position: 0 });

export default function IntegrationTab({ membershipId, webhookUrl: initialWebhook }: { membershipId: number; webhookUrl: string | null }) {
  const utils = trpc.useUtils();
  const integration = trpc.leadops.getMemberIntegration.useQuery({ membershipId }, { retry: false });
  const refresh = () => { utils.leadops.getMemberIntegration.invalidate({ membershipId }); utils.leadops.getMemberDetail.invalidate({ membershipId }); };
  if (integration.error) return <section className="surface-panel p-6 text-sm text-red-200">{integration.error.message}</section>;
  if (!integration.data) return <section className="surface-panel p-6 text-sm text-slate-400">Integration wird geladen…</section>;
  const data = integration.data;
  return <div className="grid gap-4">
    <OutgoingCalls data={data} membershipId={membershipId} onDone={refresh} />
    {/* seit v383: Die Rückmeldung des Käufers wird hier eingerichtet – an derselben Stelle wie seine Schnittstelle */}
    <BuyerFeedback membershipId={membershipId} />
    <ResponseMapping data={data} membershipId={membershipId} onDone={refresh} />
    <ReturnWebhooks data={data} membershipId={membershipId} onDone={refresh} />
    <WebhookBlock data={data} membershipId={membershipId} initialWebhook={initialWebhook} onDone={refresh} />
  </div>;
}

function OutgoingCalls({ data, membershipId, onDone }: { data: Integration; membershipId: number; onDone: () => void }) {
  const [openCategory, setOpenCategory] = useState<number | null>(null);
  const [editing, setEditing] = useState<Endpoint | null>(null);
  const [presetPicker, setPresetPicker] = useState<{ kind: "endpoint" | "return_webhook" | "response_mapping"; categoryId: number | null } | null>(null);
  return <section className="surface-panel operations-panel min-w-0 p-5 fx-scope it-section" aria-label="Schnittstelle zu diesem Käufer"><div className="flex items-start justify-between gap-3"><div><h3 className="fx-h">Schnittstelle zu diesem Käufer</h3><p className="it-intro">Über die Schnittstelle geht jeder Lead, der diesem Käufer zugewiesen wird, direkt in sein System – je Lead-Kategorie eine oder mehrere Adressen, wenn du willst nach Quelle getrennt und mit deinen eigenen Feldern.</p></div><Button size="sm" variant="outline" onClick={() => setPresetPicker({ kind: "endpoint", categoryId: null })}>Preset hinzufügen</Button></div>
    {presetPicker && <PresetPicker kind={presetPicker.kind} membershipId={membershipId} categoryId={presetPicker.categoryId} categories={data.categories} onClose={() => setPresetPicker(null)} onDone={() => { setPresetPicker(null); onDone(); }} />}
    <div className="mt-3 grid grid-cols-[minmax(0,1fr)] gap-2">{data.categories.map((category) => { const endpoints = data.endpoints.filter((endpoint) => endpoint.categoryId === category.id); const open = openCategory === category.id; return <div key={category.id} className="rounded-lg border border-white/8 bg-white/[.02]"><button type="button" className="flex w-full items-center justify-between gap-2 p-3 text-left" onClick={() => setOpenCategory(open ? null : category.id)}><span className="text-sm text-slate-100">{category.name} <span className="text-xs text-slate-500">{category.shortcode}</span></span><Badge variant="outline" className={endpoints.length ? "border-emerald-400/25 bg-emerald-500/10 text-emerald-200" : "border-white/15 text-slate-400"}>{endpoints.length ? `${endpoints.length} Endpoint${endpoints.length > 1 ? "s" : ""}` : "Nicht eingerichtet"}</Badge></button>
      {open && <div className="border-t border-white/8 p-3">{endpoints.map((endpoint, index) => <div key={endpoint.id} className="mb-2 flex flex-wrap items-center gap-2 rounded-md border border-white/8 bg-black/20 px-3 py-2 text-sm"><span className="text-xs text-slate-500">{index + 1}</span><code className="min-w-0 max-w-full truncate text-xs text-slate-200" title={endpoint.url}>{endpoint.url}</code><Badge variant="outline" className="border-white/15 text-slate-300">{endpoint.method}</Badge>{endpoint.sourceFilterMode !== "alle" && <Badge variant="outline" className="border-white/15 text-slate-300">Quellen: {endpoint.sourceSupplierIds.length}</Badge>}{endpoint.rotate && <Badge variant="outline" className="border-white/15 text-slate-300">Round-Robin</Badge>}<span className={`ml-auto text-xs ${endpoint.enabled ? "text-emerald-300" : "text-slate-500"}`}>● {endpoint.enabled ? "Aktiv" : "Inaktiv"}</span><Button size="sm" variant="ghost" onClick={() => setEditing(endpoint)}>Bearbeiten</Button></div>)}<div className="flex gap-1"><Button size="sm" variant="outline" onClick={() => setEditing(emptyEndpoint(category.id))}>Endpoint hinzufügen</Button><Button size="sm" variant="ghost" onClick={() => setPresetPicker({ kind: "endpoint", categoryId: category.id })}>Aus Preset</Button></div></div>}
    </div>; })}</div>
    {editing && <EndpointEditor key={editing.id || "new"} data={data} membershipId={membershipId} endpoint={editing} onClose={() => setEditing(null)} onDone={() => { setEditing(null); onDone(); }} />}
  </section>;
}

function EndpointEditor({ data, membershipId, endpoint, onClose, onDone }: { data: Integration; membershipId: number; endpoint: Endpoint; onClose: () => void; onDone: () => void }) {
  const [form, setForm] = useState<Endpoint>(endpoint);
  const [testResult, setTestResult] = useState<{ ok: boolean; status: number; responseBody: string; requestBody: string; loginOnly?: boolean } | null>(null);
  const [testLeads, setTestLeads] = useState<{ sent: number; ok: number; total: number; results: Array<{ label: string; ok: boolean; status: number; reference: string | null; response: string; requestBody: string }> } | null>(null);
  /** Zugangsdaten: Zeile → Wert lesbar (Auge). Ohne Klick: Benutzername lesbar, alles andere als Punkte. */
  const [shownSecrets, setShownSecrets] = useState<Record<number, boolean>>({});
  const fields = data.customFields.filter((item) => item.categoryId === form.categoryId);
  const set = <K extends keyof Endpoint>(key: K, value: Endpoint[K]) => setForm((current) => ({ ...current, [key]: value }));
  const save = trpc.leadops.saveDeliveryEndpoint.useMutation({ onSuccess: () => { toast.success(isWattfoxTemplate(form.bodyTemplate) && !isTestAddress(form.url) ? "Gespeichert – jetzt den Endpoint wieder öffnen und unten rechts „Anmeldung prüfen“ klicken. Dabei geht kein Lead raus." : "Endpoint gespeichert."); onDone(); }, onError: (error) => toast.error(error.message) });
  const remove = trpc.leadops.deleteDeliveryEndpoint.useMutation({ onSuccess: () => { toast.success("Endpoint gelöscht."); onDone(); }, onError: (error) => toast.error(error.message) });
  const duplicate = trpc.leadops.duplicateDeliveryEndpoint.useMutation({ onSuccess: () => { toast.success("Kopie angelegt (inaktiv)."); onDone(); }, onError: (error) => toast.error(error.message) });
  const test = trpc.leadops.testDeliveryEndpoint.useMutation({ onSuccess: (result) => { setTestResult(result); toast[result.ok ? "success" : "error"](result.loginOnly ? (result.ok ? "Anmeldung bei Wattfox klappt – kein Lead gesendet" : "Anmeldung bei Wattfox fehlgeschlagen – kein Lead gesendet") : `Test: HTTP ${result.status}`); }, onError: (error) => toast.error(error.message) });
  const wattfoxTests = trpc.leadops.sendWattfoxTestLeads.useMutation({ onSuccess: (result) => { setTestLeads(result); toast[result.ok === result.total ? "success" : "error"](`Testleads an Wattfox: ${result.ok} von ${result.total} angekommen`); }, onError: (error) => toast.error(error.message) });
  const wattfox = isWattfoxTemplate(form.bodyTemplate);
  const wattfoxHost = (url: string | null | undefined) => /wattfox|angebotsvergleich/i.test(url ?? "");
  // Wattfox-Vorlage: Anmeldung (Benutzername/Passwort → Schlüssel 24 h in X-AUTH-TOKEN), Adresse der Testumgebung, Body mit Herkunft – eingetragene Zugangsdaten bleiben
  /** Gespeicherter Stand zeigt auf das Live-System von Wattfox → „Test senden“ prüft nur die Anmeldung, keine Testleads */
  const savedWattfoxLive = isWattfoxTemplate(endpoint.bodyTemplate) && !isTestAddress(endpoint.url) && form.id > 0;
  /**
   * Live-System ↔ Testumgebung: beide Adressen tauschen. Benutzername und Passwort bleiben stehen (seit v365) –
   * oft ist der Live-Zugang schon eingetippt, und ein gespeichertes Passwort (z. B. aus einem Einmal-Link) gäbe es sonst nicht mehr.
   * Stimmt der Zugang nicht, sagt es „Anmeldung prüfen“ – ohne dass ein Lead rausgeht.
   */
  const switchWattfoxSystem = (target: "live" | "test") => {
    setForm((current) => ({ ...current, url: target === "live" ? WATTFOX.liveLeadsUrl : WATTFOX.leadsUrl, auth: { ...(current.auth ?? { tokenPath: WATTFOX.tokenPath, headerName: WATTFOX.tokenHeader, prefix: "", ttlMinutes: WATTFOX.tokenMinutes, credentials: [{ name: "user", value: "" }, { name: "pass", value: "" }] }), loginUrl: target === "live" ? WATTFOX.liveLoginUrl : WATTFOX.loginUrl } }));
    toast.success(target === "live" ? "Live-Adresse eingesetzt. Benutzername und Passwort bleiben stehen – steht dort noch der Test-Zugang, den Live-Zugang eintippen. Dann speichern, wieder öffnen und „Anmeldung prüfen“ klicken. Dabei geht kein Lead raus." : "Testumgebung eingesetzt. Benutzername und Passwort bleiben stehen – für Testleads den Test-Zugang eintippen und speichern.");
  };
  /** Adresse im Formular gewechselt, aber noch nicht gespeichert: Prüfen und Testleads liefen noch an die alte Adresse – erst speichern */
  const addressUnsaved = form.id > 0 && wattfox && isTestAddress(form.url) !== isTestAddress(endpoint.url);
  /** Zwei Adressen hintereinander (alte beim Einfügen nicht gelöscht) – Hinweis unter dem Feld, Speichern gesperrt (seit v365) */
  const gluedUrl = hasGluedAddress(form.url);
  const gluedLogin = form.authEnabled && hasGluedAddress(form.auth?.loginUrl);
  const applyWattfox = () => { setForm((current) => { const before = current.auth; const credential = (name: string) => before?.credentials.find((pair) => pair.name === name)?.value ?? ""; return { ...current, url: wattfoxHost(current.url) ? current.url : WATTFOX.leadsUrl, method: "POST", authEnabled: true, auth: { loginUrl: wattfoxHost(before?.loginUrl) ? before!.loginUrl : WATTFOX.loginUrl, credentials: [{ name: "user", value: credential("user") }, { name: "pass", value: credential("pass") }], tokenPath: WATTFOX.tokenPath, headerName: WATTFOX.tokenHeader, prefix: "", ttlMinutes: WATTFOX.tokenMinutes }, bodyTemplate: WATTFOX_TEMPLATE, omitAutoFields: true }; }); toast.success("Wattfox-Vorlage eingesetzt – jetzt unter „Zugangsdaten“ neben „user“ den Benutzernamen und neben „pass“ das Passwort von Wattfox eintippen und speichern."); };
  const sendWattfoxTests = async (all = false) => { const live = !isTestAddress(form.url); if (live && !(await confirmAction(`Die Adresse sieht nach dem Live-System von Wattfox aus. Trotzdem die ${all ? 9 : 3} erfundenen Testleads dorthin senden?`, { confirmLabel: "Trotzdem senden", danger: true }))) return; setTestLeads(null); wattfoxTests.mutate({ membershipId, id: form.id, allowLive: live || undefined, all: all || undefined }); };
  const copyTestNumbers = () => { if (!testLeads) return; const lines = testLeads.results.map((item) => `${item.label}: ${item.reference ?? (item.ok ? "angekommen" : `HTTP ${item.status || "–"}`)}`); void navigator.clipboard?.writeText(`Testleads eingesendet (Tanesco Digital GbR):\n${lines.join("\n")}`).then(() => toast.success("Nummern kopiert – zum Einfügen in die Mail an Wattfox."), () => toast.error("Kopieren ging nicht.")); };
  const presetSave = trpc.leadops.saveEndpointPreset.useMutation({ onSuccess: () => toast.success("Als Preset gespeichert – bei anderen Benutzern über „Preset hinzufügen“ verfügbar."), onError: (error) => toast.error(error.message) });
  const saveAsPreset = async () => { const name = await promptAction("Name des Presets (z. B. „Aroundhome Lead-API“):", ""); if (!name?.trim()) return; const includeSecrets = await confirmAction("Schlüssel und Zugangsdaten mit ins Preset übernehmen? (OK = ja, alle Benutzer bekommen dieselben Schlüssel · Abbrechen = nein, Schlüssel werden beim Hinzufügen abgefragt)"); presetSave.mutate({ membershipId, endpointId: form.id, name: name.trim(), includeSecrets }); };
  const payload = () => ({ membershipId, id: form.id || undefined, categoryId: form.categoryId, enabled: form.enabled, method: form.method, url: form.url, sourceFilterMode: form.sourceFilterMode, sourceSupplierIds: form.sourceSupplierIds, fieldFilters: form.fieldFilters, headers: form.headers, authEnabled: form.authEnabled, auth: form.authEnabled ? (form.auth ?? { loginUrl: "", credentials: [], tokenPath: "token", headerName: "Authorization", prefix: "Bearer", ttlMinutes: null }) : null, bodyTemplate: form.bodyTemplate, omitAutoFields: form.omitAutoFields, rotate: form.rotate, valueMappings: form.valueMappings });
  const insertPlaceholder = (key: string) => { const textarea = document.getElementById(`body-${endpoint.id}`) as HTMLTextAreaElement | null; const token = `{{${key}}}`; if (!textarea) return set("bodyTemplate", form.bodyTemplate + token); const start = textarea.selectionStart ?? form.bodyTemplate.length; const end = textarea.selectionEnd ?? start; set("bodyTemplate", form.bodyTemplate.slice(0, start) + token + form.bodyTemplate.slice(end)); };
  const auth = form.auth ?? { loginUrl: "", credentials: [{ name: "user", value: "" }, { name: "pass", value: "" }], tokenPath: "auth_token", headerName: "X-AUTH-TOKEN", prefix: "", ttlMinutes: 1380 };
  const suppliers = data.suppliers;
  return <div className="fixed inset-0 z-50 overflow-y-auto bg-black/60 px-4 py-6" onClick={onClose}><section className="surface-panel ig-dialog mx-auto w-full max-w-4xl p-6" onClick={(event) => event.stopPropagation()}>
    <div className="flex items-start justify-between gap-3"><div><span className="eyebrow">ENDPOINT</span><h2 className="mt-1 text-lg text-slate-100">{form.id ? "Endpoint bearbeiten" : "Neuer Endpoint"} · {data.categories.find((category) => category.id === form.categoryId)?.name}</h2></div><Button variant="ghost" size="sm" onClick={onClose}>Schließen</Button></div>
    <div className="mt-4 grid gap-3 md:grid-cols-[120px_1fr]"><Toggle checked={form.enabled} onChange={(value) => set("enabled", value)} label="Call aktiv" /><div className="grid gap-2 md:grid-cols-[120px_1fr]"><select className={field} value={form.method} onChange={(event) => set("method", event.target.value as Endpoint["method"])}><option>POST</option><option>PUT</option><option>PATCH</option></select><Input value={form.url} aria-invalid={gluedUrl || undefined} onChange={(event) => set("url", event.target.value)} placeholder="https://api.dein-system.de/leads" />{gluedUrl && <p className="ig-glued md:col-span-2 rounded-md border border-red-400/25 bg-red-500/10 px-2 py-1 text-[11px] text-red-200">{GLUED_ADDRESS_HINT}</p>}</div></div>
    <div className="mt-4 grid gap-3 md:grid-cols-2">
      <div className="rounded-lg border border-white/8 p-3"><span className="eyebrow">QUELL-FILTER</span><p className="mt-1 text-[11px] text-slate-500">Steuere, welche Leads dieser Endpoint erhält — anhand der Lead-Quelle (Lieferant/Kampagne). So kann ein Käufer verschiedene Quellen an verschiedene Endpoints ausliefern.</p><select className={`${field} mt-2`} value={form.sourceFilterMode} onChange={(event) => set("sourceFilterMode", event.target.value as Endpoint["sourceFilterMode"])}><option value="alle">Alle Quellen</option><option value="nur">Nur diese Quellen</option><option value="ausser">Alle außer diesen Quellen</option></select>{form.sourceFilterMode !== "alle" && <div className="mt-2 flex flex-wrap gap-1">{suppliers.map((supplier) => { const active = form.sourceSupplierIds.includes(supplier.id); return <button key={supplier.id} type="button" className={`rounded-full border px-2 py-0.5 text-xs ${active ? "border-violet-400/40 bg-violet-500/15 text-violet-100" : "border-white/10 text-slate-400"}`} onClick={() => set("sourceSupplierIds", active ? form.sourceSupplierIds.filter((id) => id !== supplier.id) : [...form.sourceSupplierIds, supplier.id])}>{supplier.name}</button>; })}</div>}</div>
      <div className="rounded-lg border border-white/8 p-3"><span className="eyebrow">FELD-FILTER (OPTIONAL)</span><p className="mt-1 text-[11px] text-slate-500">Steuere, welche Leads dieser Endpoint erhält — anhand von Lead-Feldern (z. B. Land = CH). Leer = jeder Lead.</p>{form.fieldFilters.map((filter, index) => <div key={index} className="mt-2 grid gap-1 md:grid-cols-[1fr_120px_1fr_auto]"><select className={field} value={filter.field} onChange={(event) => set("fieldFilters", form.fieldFilters.map((item, i) => i === index ? { ...item, field: event.target.value } : item))}><option value="">Feld wählen …</option>{["country_code", "postal_code", "city"].map((key) => <option key={key} value={key}>{key}</option>)}{fields.map((item) => <option key={item.fieldKey} value={item.fieldKey}>{item.label} ({item.fieldKey})</option>)}</select><select className={field} value={filter.op} onChange={(event) => set("fieldFilters", form.fieldFilters.map((item, i) => i === index ? { ...item, op: event.target.value as "gleich" | "enthaelt" } : item))}><option value="gleich">Ist gleich</option><option value="enthaelt">Enthält</option></select><Input value={filter.value} onChange={(event) => set("fieldFilters", form.fieldFilters.map((item, i) => i === index ? { ...item, value: event.target.value } : item))} placeholder="Wert" /><Button size="sm" variant="ghost" onClick={() => set("fieldFilters", form.fieldFilters.filter((_, i) => i !== index))}>✕</Button></div>)}{!form.fieldFilters.length && <p className="mt-2 text-xs text-slate-500">Noch kein Filter gesetzt.</p>}<Button size="sm" variant="outline" className="mt-2" onClick={() => set("fieldFilters", [...form.fieldFilters, { field: "", op: "gleich", value: "" }])}>Filter hinzufügen</Button></div>
    </div>
    <div className="mt-4 rounded-lg border border-white/8 p-3"><span className="eyebrow">HEADER (OPTIONAL)</span>{form.headers.map((pair, index) => <div key={index} className="mt-2 grid gap-1 md:grid-cols-[1fr_2fr_auto]"><Input value={pair.name} placeholder="Authorization" onChange={(event) => set("headers", form.headers.map((item, i) => i === index ? { ...item, name: event.target.value } : item))} /><Input value={pair.value} placeholder="Bearer …" onChange={(event) => set("headers", form.headers.map((item, i) => i === index ? { ...item, value: event.target.value } : item))} /><Button size="sm" variant="ghost" onClick={() => set("headers", form.headers.filter((_, i) => i !== index))}>✕</Button></div>)}<Button size="sm" variant="outline" className="mt-2" onClick={() => set("headers", [...form.headers, { name: "", value: "" }])}>Header hinzufügen</Button></div>
    <div className="ig-auth mt-4"><Toggle checked={form.authEnabled} onChange={(value) => set("authEnabled", value)} label="Anmeldung nötig (Token statt festem Schlüssel)" hint="Manche Partner geben keinen dauerhaften Schlüssel aus: Man meldet sich mit Zugangsdaten an, bekommt einen zeitlich begrenzten Token und schickt ihn bei jeder Zustellung mit. Aus bleibt der bisherige Weg mit festen Kopfzeilen." />
      {form.authEnabled && <div className="mt-2 grid gap-2 rounded-lg border border-white/8 p-3 md:grid-cols-2"><label className="text-xs text-slate-300 md:col-span-2">Anmelde-Adresse (POST)<Input value={auth.loginUrl} aria-invalid={gluedLogin || undefined} placeholder="https://partner.example/login" onChange={(event) => set("auth", { ...auth, loginUrl: event.target.value })} />{gluedLogin && <span className="ig-glued mt-1 block rounded-md border border-red-400/25 bg-red-500/10 px-2 py-1 text-[11px] text-red-200">{GLUED_ADDRESS_HINT}</span>}</label><div className="md:col-span-2"><span className="block text-xs text-slate-300">Zugangsdaten (Feldnamen wie vom Partner vorgegeben)</span><p className="ig-credentials-hint mt-0.5 text-[11px] text-slate-500">Benutzername und Passwort vom Partner selbst eintippen – der Browser setzt hier nichts ein. Mit dem Auge siehst du, was du eintippst. Ein gespeichertes Passwort zeigt die Software nicht mehr an („gespeichert“) – zum Ändern oder Prüfen einfach neu eintippen und speichern.</p>{auth.credentials.map((pair, index) => { const shown = shownSecrets[index] ?? isPlainCredential(pair.name); const label = pair.name.trim() || "Zugangsfeld"; const saved = pair.value === SAVED_SECRET; const savedBefore = (endpoint.auth?.credentials ?? []).some((item) => item.name === pair.name && item.value === SAVED_SECRET); const ownPassword = Boolean((pair as { ownPassword?: boolean }).ownPassword); return <div key={index} className="ig-credential mt-1 grid grid-cols-[minmax(0,1fr)_auto_auto] gap-1 md:grid-cols-[1fr_2fr_auto_auto]"><Input className="col-span-3 md:col-span-1" value={pair.name} placeholder="user" autoComplete="off" spellCheck={false} aria-label={`Feldname ${index + 1}`} onChange={(event) => set("auth", { ...auth, credentials: auth.credentials.map((item, i) => i === index ? { ...item, name: event.target.value } : item) })} /><Input type="password" reveal={shown} value={saved ? "" : pair.value} placeholder={saved ? "gespeichert – zum Ändern neu eintippen" : "Wert"} aria-invalid={ownPassword || undefined} aria-label={`Wert für „${label}“`} onChange={(event) => { const value = event.target.value; set("auth", { ...auth, credentials: auth.credentials.map((item, i) => i === index ? { name: item.name, value: value === "" && savedBefore ? SAVED_SECRET : value } : item) }); }} /><Button type="button" size="sm" variant="ghost" className="ig-credential-eye" disabled={saved} aria-label={shown ? `„${label}“ verbergen` : `„${label}“ zeigen`} title={saved ? "Gespeicherte Passwörter zeigt die Software nicht an – zum Prüfen neu eintippen" : shown ? "Verbergen" : "Zeigen"} onClick={() => setShownSecrets((state) => ({ ...state, [index]: !shown }))}>{shown ? <EyeOff /> : <Eye />}</Button><Button type="button" size="sm" variant="ghost" aria-label={`„${label}“ entfernen`} onClick={() => { setShownSecrets({}); set("auth", { ...auth, credentials: auth.credentials.filter((_, i) => i !== index) }); }}>✕</Button>{ownPassword && <p className="ig-credential-own col-span-3 rounded-md border border-red-400/25 bg-red-500/10 px-2 py-1 text-[11px] text-red-200 md:col-span-4">Hier steht dein Passwort für diese Software – das hat der Browser eingesetzt. Bitte {isPlainCredential(pair.name) ? "den Benutzernamen" : "das Passwort"} vom Partner neu eintippen und speichern; so geht nichts raus.</p>}</div>; })}<Button size="sm" variant="outline" className="mt-1" onClick={() => set("auth", { ...auth, credentials: [...auth.credentials, { name: "", value: "" }] })}>+ Zugangsfeld hinzufügen</Button></div><label className="text-xs text-slate-300">Wo steht der Token in der Antwort?<Input value={auth.tokenPath} placeholder="auth_token" onChange={(event) => set("auth", { ...auth, tokenPath: event.target.value })} /></label><label className="text-xs text-slate-300">Kopfzeile für den Token<Input value={auth.headerName} placeholder="X-AUTH-TOKEN" onChange={(event) => set("auth", { ...auth, headerName: event.target.value })} /></label><label className="text-xs text-slate-300">Präfix (optional)<Input value={auth.prefix ?? ""} placeholder="z. B. Bearer – leer lassen, wenn der Partner keins will" onChange={(event) => set("auth", { ...auth, prefix: event.target.value })} /></label><label className="text-xs text-slate-300">Gültigkeit in Minuten<Input type="number" value={auth.ttlMinutes ?? ""} placeholder="1380" onChange={(event) => set("auth", { ...auth, ttlMinutes: event.target.value === "" ? null : Number(event.target.value) })} /><span className="mt-1 block text-[11px] text-slate-500">Der Token wird zwischengespeichert und kurz vor Ablauf erneuert. Leer = vor jeder Zustellung neu anmelden. Beispiel: 24 Stunden Gültigkeit → 1380 eintragen. Bei „nicht berechtigt“ meldet sich das System einmal neu an und wiederholt.</span></label></div>}
    </div>
    <div className="ig-body mt-4 rounded-lg border border-white/8 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><span className="eyebrow">BODY</span><Button size="sm" variant="ghost" onClick={() => set("bodyTemplate", `{\n  "publisher_id": "<Publisher-ID>",\n  "sub_id": "{{custom_data.d2d_sub_id}}",\n  "external_id": "{{lead_id}}",\n  "lead_type": "{{lead_type_shortcode}}",\n  "contact": {\n    "salutation": "{{salutation}}",\n    "first_name": "{{first_name}}",\n    "last_name": "{{last_name}}",\n    "email": "{{email}}",\n    "phone": "{{phone}}",\n    "street": "{{street}}",\n    "zip_code": "{{postal_code}}",\n    "city": "{{city}}",\n    "country_code": "{{country_code}}"\n  },\n  "consent": "{{custom_data.consent}}"\n}`)}>Vorlage Aroundhome (mit Sub-ID)</Button><Button size="sm" variant="ghost" className="ig-wattfox-template" onClick={applyWattfox}>Vorlage Wattfox</Button></div>{wattfox && <div className="ig-wattfox-note mt-2 rounded-md border border-cyan-400/20 bg-cyan-500/[.06] p-3 text-xs leading-5 text-slate-200"><b className="block text-slate-100">Wattfox-Vorlage: Die Felder baut die Software selbst.</b>Photovoltaik geht als Produkt 2 raus, Wärmepumpe als Heizung (20) mit dem Zusatz Wärmepumpe (6). Will jemand beides, geht ein Lead mit Zusatzinteresse raus. Unsere Angaben werden in die Werte von Wattfox übersetzt; was nur ungefähr passt, steht zusätzlich im Hinweisfeld – ebenso alles Weitere, was wir über den Kunden wissen (ohne Aufnahme, Agent und Herkunft der Anzeige). Die Telefonnummer geht immer international raus („+49…“), nie als „49…“. Hier im Body stehen nur die Herkunftsangaben – „utm_source“ und „utm_medium“ nie ändern. „utm_campaign“ zeigt den Callagents von Wattfox die Marke, unter der der Kunde gewonnen wurde („Hauskompass, Meta vorqualifiziert“) – nur nach Rücksprache mit Wattfox ändern.<span className="mt-1 block text-slate-400">Fehlt eine Pflichtangabe (Anrede, Name, Anschrift, Telefon, E-Mail), geht der Lead nicht raus und steht unter „API-Fehler“. </span>{(() => { const check = wattfoxOriginCheck(form.bodyTemplate); if (!check) return null; return <span className={`ig-wattfox-origin mt-2 block rounded-md px-2 py-1.5 ${check.ok ? "is-ok" : "is-warn"}`}>{check.ok ? <>Herkunft geprüft: genau wie mit Wattfox vereinbart – „{String(check.sent.utm_campaign)}“.</> : <>{check.problems.map((problem) => <span key={problem} className="block">{problem}</span>)}<Button type="button" size="sm" variant="outline" className="ig-wattfox-fix mt-1.5" onClick={() => set("bodyTemplate", wattfoxTemplateWithAgreedOrigin(form.bodyTemplate))}>Vereinbarte Herkunft einsetzen</Button></>}</span>; })()}<span className="ig-wattfox-address mt-2 flex flex-wrap items-center gap-2 text-slate-300">Adresse jetzt: <b>{isTestAddress(form.url) ? "Testumgebung von Wattfox" : "Live-System von Wattfox"}</b><Button type="button" size="sm" variant="outline" className="ig-wattfox-live" onClick={() => switchWattfoxSystem(isTestAddress(form.url) ? "live" : "test")}>{isTestAddress(form.url) ? "Live-Adresse einsetzen" : "Testumgebung einsetzen"}</Button></span><span className="mt-1 block text-slate-400">{isTestAddress(form.url) ? "Für echte Leads: „Live-Adresse einsetzen“ (Benutzername und Passwort bleiben stehen), falls nötig den Live-Zugang eintippen, speichern, wieder öffnen und „Anmeldung prüfen“ klicken – dabei geht kein Lead raus." : "Live: „Anmeldung prüfen“ zeigt, ob Adresse und Zugang stimmen – dabei geht kein Lead raus. Testleads gehen nur an die Testumgebung."}</span></div>}
      {!wattfox && <p className="mt-1 text-[11px] text-slate-500">Wir fügen jedem Call automatisch das Feld lead_id (unsere Lead-ID) im JSON-Body hinzu — du musst es nicht selbst eintragen oder mappen. Der Empfänger braucht es, um den Lead per API zu reklamieren.</p>}<textarea id={`body-${endpoint.id}`} className="mt-2 min-h-[220px] w-full rounded-md border border-white/10 bg-slate-950 p-3 font-mono text-xs text-slate-100" value={form.bodyTemplate} onChange={(event) => set("bodyTemplate", event.target.value)} placeholder={`{\n  "first_name": "{{first_name}}",\n  "last_name": "{{last_name}}",\n  "email": "{{email}}",\n  "phone": "{{phone}}",\n  "zip_code": "{{postal_code}}",\n  "custom": "{{custom_data.${fields[0]?.fieldKey ?? "feld"}}}"\n}`} />{!wattfox && <><p className="mt-2 text-[11px] text-slate-500">Platzhalter — Klicken fügt das Feld an der Cursor-Position ein.</p><div className="mt-1 flex flex-wrap gap-1">{data.placeholders.map((key) => <button key={key} type="button" className="rounded-full border border-white/10 px-2 py-0.5 text-[11px] text-slate-300 hover:border-violet-400/40" onClick={() => insertPlaceholder(key)}>{`{{${key}}}`}</button>)}{fields.map((item) => <button key={item.fieldKey} type="button" className="rounded-full border border-cyan-400/20 px-2 py-0.5 text-[11px] text-cyan-200 hover:border-cyan-400/50" onClick={() => insertPlaceholder(`custom_data.${item.fieldKey}`)}>{`{{custom_data.${item.fieldKey}}}`}</button>)}</div></>}
      <div className="mt-3 grid gap-2 md:grid-cols-2"><Toggle checked={form.omitAutoFields} onChange={(value) => set("omitAutoFields", value)} label="Nur Template senden — keine automatischen Felder (lead_id, lead_number)." hint="Für strenge APIs wie GoHighLevel, die unbekannte Felder ablehnen." /><Toggle checked={form.rotate} onChange={(value) => set("rotate", value)} label="Im Wechsel senden (Round-Robin)" hint="Dieser Aufruf wechselt sich mit den anderen so markierten Aufrufen derselben Kategorie ab: pro Kontakt feuert nur einer, reihum. Für mehrere Konten beim selben Partner." /></div></div>
    <div className="mt-4 rounded-lg border border-white/8 p-3"><span className="eyebrow">WERTE-MAPPING</span><p className="mt-1 text-[11px] text-slate-500">Übersetzt einen Wert dieser Kategorie in den Code, den dieser Käufer erwartet (z. B. „Familienhaus“ → „222“). Leere Zeilen werden ignoriert.</p>{form.valueMappings.map((mapping, index) => <div key={index} className="mt-2 grid gap-1 md:grid-cols-[1fr_1fr_1fr_auto]"><select className={field} value={mapping.field} onChange={(event) => set("valueMappings", form.valueMappings.map((item, i) => i === index ? { ...item, field: event.target.value } : item))}><option value="">Feld wählen …</option>{fields.map((item) => <option key={item.fieldKey} value={item.fieldKey}>{item.label} ({item.fieldKey})</option>)}</select><Input value={mapping.ourValue} placeholder="Unser Wert" onChange={(event) => set("valueMappings", form.valueMappings.map((item, i) => i === index ? { ...item, ourValue: event.target.value } : item))} /><Input value={mapping.customerCode} placeholder="Kunden-Code" onChange={(event) => set("valueMappings", form.valueMappings.map((item, i) => i === index ? { ...item, customerCode: event.target.value } : item))} /><Button size="sm" variant="ghost" onClick={() => set("valueMappings", form.valueMappings.filter((_, i) => i !== index))}>✕</Button></div>)}<Button size="sm" variant="outline" className="mt-2" onClick={() => set("valueMappings", [...form.valueMappings, { field: "", ourValue: "", customerCode: "" }])}>Mapping hinzufügen</Button></div>
    {testLeads && <div className={`ig-wattfox-tests mt-4 rounded-lg border p-3 text-xs ${testLeads.ok === testLeads.total ? "border-emerald-400/25 bg-emerald-500/10 text-emerald-100" : "border-red-400/25 bg-red-500/10 text-red-100"}`}><div className="flex flex-wrap items-center justify-between gap-2"><strong>Testleads an Wattfox: {testLeads.ok} von {testLeads.total} angekommen</strong><Button size="sm" variant="ghost" onClick={copyTestNumbers}>Nummern kopieren</Button></div><ul className="mt-2 grid gap-1">{testLeads.results.map((item) => <li key={item.label} className="rounded border border-white/8 bg-black/20 px-2 py-1"><span className="font-medium">{item.ok ? "✓" : "✕"} {item.label}</span> · HTTP {item.status || "–"}{item.reference ? ` · Wattfox-Nr. ${item.reference}` : ""}{!item.ok && <span className="block opacity-80">{item.response || "(keine Antwort)"}</span>}<details className="mt-0.5"><summary className="cursor-pointer opacity-70">Gesendet</summary><pre className="mt-1 max-h-40 overflow-auto whitespace-pre-wrap">{(() => { try { return JSON.stringify(JSON.parse(item.requestBody), null, 2); } catch { return item.requestBody; } })()}</pre></details></li>)}</ul>{testLeads.sent < testLeads.total && <p className="mt-2">Abgebrochen: Die Anmeldung bei Wattfox klappt nicht – Benutzername, Passwort und Anmelde-Adresse prüfen.</p>}</div>}
    {testResult && <div className={`mt-4 rounded-lg border p-3 text-xs ${testResult.ok ? "border-emerald-400/25 bg-emerald-500/10 text-emerald-100" : "border-red-400/25 bg-red-500/10 text-red-100"}`}><strong className="ig-test-title">{testResult.loginOnly ? (testResult.ok ? "Anmeldung: klappt" : `Anmeldung: fehlgeschlagen${testResult.status ? ` (HTTP ${testResult.status})` : ""}`) : `Test: HTTP ${testResult.status}`}</strong><pre className={`mt-1 max-h-40 overflow-auto whitespace-pre-wrap ${testResult.loginOnly ? "font-sans" : ""}`}>{testResult.responseBody || "(keine Antwort)"}</pre>{testResult.requestBody && <details className="mt-1"><summary className="cursor-pointer">Gesendeter Body</summary><pre className="mt-1 max-h-40 overflow-auto whitespace-pre-wrap">{testResult.requestBody}</pre></details>}</div>}
    <div className="mt-5 flex flex-wrap justify-between gap-2"><div className="flex gap-2">{form.id > 0 && <Button variant="ghost" size="sm" onClick={async () => { if (await confirmAction("Endpoint löschen?")) remove.mutate({ membershipId, id: form.id }); }}>Löschen</Button>}{form.id > 0 && <Button variant="ghost" size="sm" onClick={() => duplicate.mutate({ membershipId, id: form.id })}>Kopieren</Button>}{form.id > 0 && <Button variant="ghost" size="sm" onClick={saveAsPreset} disabled={presetSave.isPending}>Als Preset speichern</Button>}</div><div className="flex gap-2">{form.id > 0 && !addressUnsaved && <Button variant="outline" size="sm" className="ig-test-send" title={savedWattfoxLive ? "Prüft nur die Anmeldung im Live-System von Wattfox – es geht kein Lead raus" : undefined} onClick={() => test.mutate({ membershipId, id: form.id })} disabled={test.isPending}>{savedWattfoxLive ? (test.isPending ? "Prüft die Anmeldung …" : "Anmeldung prüfen") : "Test senden"}</Button>}{form.id > 0 && wattfox && !savedWattfoxLive && !addressUnsaved && <Button variant="outline" size="sm" className="ig-wattfox-send" title="Je ein Testlead für Photovoltaik, für Wärmepumpe und einer mit beidem" onClick={() => void sendWattfoxTests()} disabled={wattfoxTests.isPending}>{wattfoxTests.isPending ? "Sendet Testleads …" : "Testleads an Wattfox senden (3)"}</Button>}{form.id > 0 && wattfox && !savedWattfoxLive && !addressUnsaved && <Button variant="ghost" size="sm" className="ig-wattfox-send-all" title="Je 3 für Photovoltaik und Wärmepumpe und 3 mit beidem – nur, falls Wattfox so viele will" onClick={() => void sendWattfoxTests(true)} disabled={wattfoxTests.isPending}>Alle 9</Button>}<Button className="flux-button" size="sm" title={gluedUrl || gluedLogin ? "Erst die doppelte Adresse korrigieren" : undefined} onClick={() => save.mutate(payload())} disabled={save.isPending || !form.url || gluedUrl || gluedLogin}>Speichern</Button></div></div>
    {form.id === 0 && <p className="mt-2 text-right text-[11px] text-slate-500">Nach dem ersten Speichern kannst du einen Test senden{wattfox ? " – und die Testleads an Wattfox" : ""}.</p>}
    {addressUnsaved && <p className="ig-address-unsaved mt-2 rounded-md border border-amber-400/25 bg-amber-500/10 px-3 py-2 text-right text-xs text-amber-100">{isTestAddress(form.url) ? "Die Testumgebung ist noch nicht gespeichert – erst „Speichern“, dann den Endpoint wieder öffnen: Dann gibt es wieder die Testleads." : "Die Live-Adresse ist noch nicht gespeichert – erst „Speichern“, dann den Endpoint wieder öffnen: Unten rechts steht dann „Anmeldung prüfen“."}</p>}
    {form.id > 0 && wattfox && !savedWattfoxLive && !addressUnsaved && <p className="mt-2 text-right text-[11px] text-slate-500">Die Testleads gehen mit dem gespeicherten Stand raus – nach Änderungen erst speichern.</p>}
  </section></div>;
}

function ResponseMapping({ data, membershipId, onDone }: { data: Integration; membershipId: number; onDone: () => void }) {
  const [enabled, setEnabled] = useState(data.responseMappingEnabled);
  const [rules, setRules] = useState<Rule[]>(data.rules);
  useEffect(() => { setEnabled(data.responseMappingEnabled); setRules(data.rules); }, [data.responseMappingEnabled, data.rules]);
  const save = trpc.leadops.saveResponseMapping.useMutation({ onSuccess: () => { toast.success("Mapping gespeichert."); onDone(); }, onError: (error) => toast.error(error.message) });
  const preset = trpc.leadops.applyAroundhomePreset.useMutation({ onSuccess: () => { toast.success("Aroundhome-Preset geladen."); onDone(); }, onError: (error) => toast.error(error.message) });
  const savePreset = trpc.leadops.saveResponseMappingPreset.useMutation({ onSuccess: () => toast.success("Mapping als Preset gespeichert."), onError: (error) => toast.error(error.message) });
  const [pickerOpen, setPickerOpen] = useState(false);
  const update = (index: number, patch: Partial<Rule>) => setRules((current) => current.map((rule, i) => i === index ? { ...rule, ...patch } : rule));
  return <section className="surface-panel operations-panel min-w-0 p-5 fx-scope it-section" aria-label="Ablehnungen des Käufers einordnen"><h3 className="fx-h">Ablehnungen des Käufers einordnen</h3><p className="it-intro">Lehnt die Schnittstelle des Käufers einen Lead ab, nennt sie meist einen Code (zum Beispiel bei Aroundhome). Hier legst du fest, welcher Code zu welchem Reklamationsgrund wird. Bei einem Treffer wird der Lead erstattet und – wenn der Grund es vorsieht – an die nächste Station der Lieferkette gegeben. Gilt für alle Lead-Kategorien dieses Käufers.</p>
    <div className="mt-3"><Toggle checked={enabled} onChange={setEnabled} label="Ablehnungen einordnen" hint="Je Regel: worauf geschaut wird (ein Feld der Antwort wie „code“ – oder der HTTP-Status) und welcher Wert zu welchem Reklamationsgrund wird. Greift nur, wenn der Käufer den Lead ablehnt." /></div>
    <div className="table-wrap mt-3"><table className="flux-table"><thead><tr><th>Worauf</th><th>Feld</th><th>Vergleich</th><th>Wert</th><th>Bezeichnung (optional)</th><th>Reklamationsgrund</th><th>Entfernen</th></tr></thead><tbody>{rules.map((rule, index) => <tr key={index}><td><select className={field} value={rule.source} onChange={(event) => update(index, { source: event.target.value as Rule["source"] })}><option value="body">Body-Feld</option><option value="status">HTTP-Status</option></select></td><td><Input value={rule.field} placeholder="code" disabled={rule.source === "status"} onChange={(event) => update(index, { field: event.target.value })} /></td><td><select className={field} value={rule.op} onChange={(event) => update(index, { op: event.target.value as Rule["op"] })}><option value="gleich">ist genau</option><option value="beginnt">beginnt mit</option><option value="enthaelt">enthält</option></select></td><td><Input value={rule.value} placeholder="5" onChange={(event) => update(index, { value: event.target.value })} /></td><td><Input value={rule.label} onChange={(event) => update(index, { label: event.target.value })} /></td><td><select className={field} value={rule.reasonId} onChange={(event) => update(index, { reasonId: Number(event.target.value) })}><option value={0}>Grund wählen …</option>{data.reasons.map((reason) => <option key={reason.id} value={reason.id}>{reason.name}</option>)}</select></td><td><div className="flex items-center gap-1"><input type="checkbox" checked={rule.active} onChange={(event) => update(index, { active: event.target.checked })} title="Aktiv" /><Button size="sm" variant="ghost" onClick={() => setRules((current) => current.filter((_, i) => i !== index))}>✕</Button></div></td></tr>)}</tbody></table></div>
    <div className="mt-3 flex flex-wrap justify-between gap-2"><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => setRules((current) => [...current, { id: 0, source: "body", field: "code", op: "gleich", value: "", label: "", reasonId: 0, active: true }])}>Regel hinzufügen</Button><Button size="sm" variant="outline" onClick={() => preset.mutate({ membershipId })} disabled={preset.isPending}>Aroundhome-Preset laden</Button><Button size="sm" variant="ghost" onClick={() => setPickerOpen(true)}>Eigenes Preset hinzufügen</Button><Button size="sm" variant="ghost" onClick={async () => { const name = await promptAction("Name des Presets:", ""); if (name?.trim()) savePreset.mutate({ membershipId, name: name.trim() }); }} disabled={!data.rules.length || savePreset.isPending}>Als Preset speichern</Button></div>
    {pickerOpen && <PresetPicker kind="response_mapping" membershipId={membershipId} categoryId={null} categories={data.categories} onClose={() => setPickerOpen(false)} onDone={() => { setPickerOpen(false); onDone(); }} />}<Button className="flux-button" size="sm" onClick={() => save.mutate({ membershipId, enabled, rules: rules.map((rule) => ({ source: rule.source, field: rule.field || null, op: rule.op, value: rule.value, label: rule.label || null, reasonId: rule.reasonId, active: rule.active })) })} disabled={save.isPending}>Mapping speichern</Button></div>
  </section>;
}

function ReturnWebhooks({ data, membershipId, onDone }: { data: Integration; membershipId: number; onDone: () => void }) {
  const [openCategory, setOpenCategory] = useState<number | null>(null);
  return <section className="surface-panel operations-panel min-w-0 p-5 fx-scope it-section" aria-label="Rückgabe an den Lieferanten"><h3 className="fx-h">Rückgabe an den Lieferanten</h3><p className="it-intro">Nur für Lieferanten: Findet ein Lead in der ganzen Lieferkette keinen Käufer, geht er an den Lieferanten zurück. Hier hinterlegst du je Lead-Kategorie die Adresse, an die wir das melden – mit der Nummer des Leads und der Markierung „returned“.</p>
    <div className="mt-3 grid grid-cols-[minmax(0,1fr)] gap-2">{data.categories.map((category) => { const hook = data.returnWebhooks.find((item) => item.categoryId === category.id); const open = openCategory === category.id; return <div key={category.id} className="rounded-lg border border-white/8 bg-white/[.02]"><button type="button" className="flex w-full items-center justify-between gap-2 p-3 text-left" onClick={() => setOpenCategory(open ? null : category.id)}><span className="text-sm text-slate-100">{category.name} <span className="text-xs text-slate-500">{category.shortcode}</span></span><Badge variant="outline" className={hook?.enabled && hook.url ? "border-emerald-400/25 bg-emerald-500/10 text-emerald-200" : "border-white/15 text-slate-400"}>{hook?.enabled && hook.url ? "Eingerichtet" : "Nicht eingerichtet"}</Badge></button>{open && <ReturnWebhookEditor key={category.id} data={data} membershipId={membershipId} categoryId={category.id} hook={hook} onDone={onDone} />}</div>; })}</div>
  </section>;
}

function ReturnWebhookEditor({ data, membershipId, categoryId, hook, onDone }: { data: Integration; membershipId: number; categoryId: number; hook: Integration["returnWebhooks"][number] | undefined; onDone: () => void }) {
  const fields = data.customFields.filter((item) => item.categoryId === categoryId);
  const defaultTemplate = useMemo(() => { const lines = ['  "lead_id": "{{lead_id}}"', '  "lead_number": "{{lead_number}}"', '  "returned": "{{returned}}"', '  "reclaim_reason": "{{reclaim_reason}}"', '  "salutation": "{{salutation}}"', '  "first_name": "{{first_name}}"', '  "last_name": "{{last_name}}"', '  "email": "{{email}}"', '  "phone": "{{phone}}"', '  "street": "{{street}}"', '  "postal_code": "{{postal_code}}"', '  "city": "{{city}}"', '  "country_code": "{{country_code}}"', '  "lead_type": "{{lead_type_shortcode}}"']; if (fields.length) lines.push(`  "custom_data": {\n${fields.map((item) => `    "${item.fieldKey}": "{{custom_data.${item.fieldKey}}}"`).join(",\n")}\n  }`); return `{\n${lines.join(",\n")}\n}`; }, [fields]);
  const [form, setForm] = useState({ enabled: hook?.enabled ?? false, method: hook?.method ?? "POST", url: hook?.url ?? "", headers: hook?.headers ?? [], bodyTemplate: hook?.bodyTemplate || defaultTemplate, omitAutoFields: hook?.omitAutoFields ?? false });
  const save = trpc.leadops.saveSupplierReturnWebhook.useMutation({ onSuccess: () => { toast.success("Rückgabe-Webhook gespeichert."); onDone(); }, onError: (error) => toast.error(error.message) });
  const test = trpc.leadops.testSupplierReturnWebhook.useMutation({ onSuccess: (result) => toast[result.ok ? "success" : "error"](`Test: HTTP ${result.status}`), onError: (error) => toast.error(error.message) });
  const savePreset = trpc.leadops.saveReturnWebhookPreset.useMutation({ onSuccess: () => toast.success("Rückgabe-Webhook als Preset gespeichert."), onError: (error) => toast.error(error.message) });
  const [pickerOpen, setPickerOpen] = useState(false);
  const extra = ["reclaim_reason", "reclaim_reason_label", "reclaim_reason_labels", "return_reason", "returned"];
  return <div className="border-t border-white/8 p-3"><div className="grid gap-2 md:grid-cols-[120px_120px_1fr]"><Toggle checked={form.enabled} onChange={(value) => setForm((current) => ({ ...current, enabled: value }))} label="Call aktiv" /><select className={field} value={form.method} onChange={(event) => setForm((current) => ({ ...current, method: event.target.value as "POST" | "PUT" | "PATCH" }))}><option>POST</option><option>PUT</option><option>PATCH</option></select><Input value={form.url} placeholder="https://dein-system.de/…" onChange={(event) => setForm((current) => ({ ...current, url: event.target.value }))} /></div>
    <div className="mt-2">{form.headers.map((pair, index) => <div key={index} className="mt-1 grid gap-1 md:grid-cols-[1fr_2fr_auto]"><Input value={pair.name} placeholder="Authorization" onChange={(event) => setForm((current) => ({ ...current, headers: current.headers.map((item, i) => i === index ? { ...item, name: event.target.value } : item) }))} /><Input value={pair.value} placeholder="Bearer …" onChange={(event) => setForm((current) => ({ ...current, headers: current.headers.map((item, i) => i === index ? { ...item, value: event.target.value } : item) }))} /><Button size="sm" variant="ghost" onClick={() => setForm((current) => ({ ...current, headers: current.headers.filter((_, i) => i !== index) }))}>✕</Button></div>)}<Button size="sm" variant="outline" className="mt-1" onClick={() => setForm((current) => ({ ...current, headers: [...current.headers, { name: "", value: "" }] }))}>Header hinzufügen</Button></div>
    <textarea className="mt-2 min-h-[180px] w-full rounded-md border border-white/10 bg-slate-950 p-3 font-mono text-xs text-slate-100" value={form.bodyTemplate} onChange={(event) => setForm((current) => ({ ...current, bodyTemplate: event.target.value }))} />
    <div className="mt-1 flex flex-wrap gap-1">{[...data.placeholders, ...extra].map((key) => <button key={key} type="button" className="rounded-full border border-white/10 px-2 py-0.5 text-[11px] text-slate-300" onClick={() => setForm((current) => ({ ...current, bodyTemplate: current.bodyTemplate + `{{${key}}}` }))}>{`{{${key}}}`}</button>)}</div>
    <div className="mt-2"><Toggle checked={form.omitAutoFields} onChange={(value) => setForm((current) => ({ ...current, omitAutoFields: value }))} label="Nur Template senden — keine automatischen Felder (lead_id, lead_number)." /></div>
    <div className="mt-3 flex justify-end gap-2"><Button variant="ghost" size="sm" onClick={() => setPickerOpen(true)}>Aus Preset</Button><Button variant="ghost" size="sm" onClick={async () => { const name = await promptAction("Name des Presets:", ""); if (name?.trim()) savePreset.mutate({ membershipId, categoryId, name: name.trim(), includeSecrets: await confirmAction("Schlüssel mit übernehmen?") }); }} disabled={!hook?.url || savePreset.isPending}>Als Preset speichern</Button>{pickerOpen && <PresetPicker kind="return_webhook" membershipId={membershipId} categoryId={categoryId} categories={data.categories} onClose={() => setPickerOpen(false)} onDone={() => { setPickerOpen(false); onDone(); }} />}<Button variant="outline" size="sm" onClick={() => test.mutate({ membershipId, categoryId })} disabled={!hook?.url || test.isPending}>Test senden</Button><Button className="flux-button" size="sm" onClick={() => save.mutate({ membershipId, categoryId, ...form })} disabled={save.isPending}>Speichern</Button></div></div>;
}

function WebhookBlock({ data, membershipId, initialWebhook, onDone }: { data: Integration; membershipId: number; initialWebhook: string | null; onDone: () => void }) {
  const [url, setUrl] = useState(data.webhookUrl ?? initialWebhook ?? "");
  const [categoryId, setCategoryId] = useState<number | null>(null);
  const save = trpc.leadops.updateMemberWebhook.useMutation({ onSuccess: () => { toast.success("Webhook gespeichert."); onDone(); }, onError: (error) => toast.error(error.message) });
  const test = trpc.leadops.sendMemberWebhookTest.useMutation({ onSuccess: (result) => toast[result.ok ? "success" : "error"](`Webhook-Test: HTTP ${result.status} ${result.body ? `· ${result.body.slice(0, 80)}` : ""}`), onError: (error) => toast.error(error.message) });
  return <section className="surface-panel operations-panel min-w-0 p-5 fx-scope it-section" aria-label="Einfache Benachrichtigung"><div className="grid gap-4 md:grid-cols-2"><div><h3 className="fx-h">Einfache Benachrichtigung (Webhook)</h3><p className="it-intro">Zusätzlich zur E-Mail: Bei jedem Lead, der diesem Käufer zugewiesen wird, schicken wir die Daten an diese Adresse. Für Käufer ohne eigene Schnittstelle der schnellste Weg.</p><div className="mt-2 flex gap-1"><Input value={url} placeholder="https://hooks.zapier.com/…" onChange={(event) => setUrl(event.target.value)} /><Button className="flux-button" size="sm" onClick={() => save.mutate({ membershipId, webhookUrl: url.trim() || null })} disabled={save.isPending}>Speichern</Button></div></div>
    <div><h3 className="fx-h is-sub">Benachrichtigung testen</h3><p className="it-intro">Schickt einen Test-Lead an die hinterlegte Adresse – genau wie ein echter Lead, nur mit der Markierung „test“.</p><div className="mt-2 flex gap-1"><select className={field} value={categoryId ?? ""} onChange={(event) => setCategoryId(event.target.value ? Number(event.target.value) : null)}><option value="">Generischer Test-Lead</option>{data.categories.map((category) => <option key={category.id} value={category.id}>{category.name} ({category.shortcode})</option>)}</select><Button variant="outline" size="sm" onClick={() => test.mutate({ membershipId, categoryId })} disabled={!data.webhookUrl || test.isPending}>Test senden</Button></div></div></div></section>;
}


/** Preset auswählen und beim Benutzer hinzufügen – fehlende Schlüssel werden abgefragt, URL/Kategorie können angepasst werden. */
function PresetPicker({ kind, membershipId, categoryId, categories, onClose, onDone }: { kind: "endpoint" | "response_mapping" | "return_webhook"; membershipId: number; categoryId: number | null; categories: Integration["categories"]; onClose: () => void; onDone: () => void }) {
  const presets = trpc.leadops.listIntegrationPresets.useQuery(undefined, { retry: false });
  const [selected, setSelected] = useState<number | null>(null);
  const requirements = trpc.leadops.integrationPresetRequirements.useQuery({ presetId: selected ?? 0 }, { retry: false, enabled: Boolean(selected) });
  const [form, setForm] = useState<{ categoryId: string; url: string; headers: Record<string, string>; auth: Record<string, string> }>({ categoryId: categoryId ? String(categoryId) : "", url: "", headers: {}, auth: {} });
  const apply = trpc.leadops.applyIntegrationPreset.useMutation({ onSuccess: (result) => { toast.success(result.kind === "response_mapping" ? `Mapping-Preset hinzugefügt (${result.count} neue Regeln).` : "Preset hinzugefügt."); onDone(); }, onError: (error) => toast.error(error.message) });
  const list = (presets.data ?? []).filter((preset) => preset.kind === kind);
  const req = requirements.data;
  useEffect(() => { if (req?.categoryId && !form.categoryId) setForm((state) => ({ ...state, categoryId: String(req.categoryId) })); }, [req?.categoryId]);
  return <div className="fixed inset-0 z-50 overflow-y-auto bg-black/60 px-4 py-6" onClick={onClose}><section className="surface-panel mx-auto w-full max-w-2xl p-6" onClick={(event) => event.stopPropagation()}><div className="flex items-start justify-between gap-3"><div><span className="eyebrow">PRESET HINZUFÜGEN</span><h2 className="mt-1 text-lg text-slate-100">{kind === "endpoint" ? "Ausgehenden API-Call aus Preset" : kind === "response_mapping" ? "Response-Mapping aus Preset" : "Rückgabe-Webhook aus Preset"}</h2><p className="mt-1 text-xs text-slate-400">Presets entstehen bei einem Benutzer über „Als Preset speichern“ und lassen sich hier bei jedem anderen Benutzer mit einem Klick übernehmen.</p></div><Button variant="ghost" size="sm" onClick={onClose}>Schließen</Button></div>
    <div className="mt-4 grid gap-2">{list.map((preset) => <button key={preset.id} type="button" className={`rounded-lg border p-3 text-left ${selected === preset.id ? "border-violet-400/40 bg-violet-500/10" : "border-white/8 bg-white/[.02]"}`} onClick={() => setSelected(preset.id)}><div className="flex flex-wrap items-center gap-2 text-sm text-slate-100"><strong>{preset.name}</strong>{preset.categoryShortcode && <Badge variant="outline" className="border-white/15 text-slate-300">{preset.categoryShortcode}</Badge>}<span className="text-xs text-slate-500">{preset.summary}</span><span className="ml-auto text-xs text-slate-500">{preset.usageCount}× verwendet</span></div>{preset.description && <div className="mt-1 text-xs text-slate-400">{preset.description}</div>}</button>)}{!list.length && <p className="text-sm text-slate-500">Noch kein Preset dieser Art. Speichere zuerst bei einem Benutzer eine Konfiguration als Preset.</p>}</div>
    {selected && req && <div className="mt-4 grid gap-3 rounded-lg border border-white/8 p-3">{kind !== "response_mapping" && <label className="text-xs text-slate-300">Lead-Kategorie<select className={field} value={form.categoryId} onChange={(event) => setForm((state) => ({ ...state, categoryId: event.target.value }))}><option value="">— wählen —</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name} ({category.shortcode})</option>)}</select></label>}{req.url && <label className="text-xs text-slate-300">URL (leer = wie im Preset: {req.url})<Input value={form.url} placeholder={req.url} onChange={(event) => setForm((state) => ({ ...state, url: event.target.value }))} /></label>}{req.headers.filter((pair) => pair.missing).map((pair) => <label key={pair.name} className="text-xs text-slate-300">Header {pair.name} (im Preset ohne Wert – bitte Schlüssel dieses Benutzers eintragen)<Input value={form.headers[pair.name] ?? ""} onChange={(event) => setForm((state) => ({ ...state, headers: { ...state.headers, [pair.name]: event.target.value } }))} /></label>)}{req.authCredentials.filter((pair) => pair.missing).map((pair) => <label key={pair.name} className="text-xs text-slate-300">Zugangsdaten {pair.name}<Input type="password" value={form.auth[pair.name] ?? ""} onChange={(event) => setForm((state) => ({ ...state, auth: { ...state.auth, [pair.name]: event.target.value } }))} /></label>)}</div>}
    <div className="mt-4 flex justify-end gap-2"><Button variant="ghost" size="sm" onClick={onClose}>Abbrechen</Button><Button className="flux-button" size="sm" disabled={!selected || apply.isPending || (kind !== "response_mapping" && !form.categoryId)} onClick={() => { if (!selected || !req) return; const headers = req.headers.map((pair) => ({ name: pair.name, value: form.headers[pair.name] ?? "" })); const authCredentials = req.authCredentials.map((pair) => ({ name: pair.name, value: form.auth[pair.name] ?? "" })); apply.mutate({ presetId: selected, membershipId, categoryId: form.categoryId ? Number(form.categoryId) : null, url: form.url || null, headers: headers.some((pair) => pair.value) ? headers : null, authCredentials: authCredentials.some((pair) => pair.value) ? authCredentials : null }); }}>Hinzufügen</Button></div></section></div>;
}
